{
  "findings": [
    {
      "check_id": "CKV_AZURE_41",
      "title": "Ensure that the expiration date is set on all secrets",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret 'database_connection_string' does not have an expiration date set, which can lead to the secret being valid indefinitely."
    },
    {
      "check_id": "CKV_AZURE_114",
      "title": "Ensure that key vault secrets have 'content_type' set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The secret 'database_connection_string' lacks a content type, making its purpose unclear upon retrieval."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n  expiration_date = timeadd(timestamp(), \"8760h\")\n  content_type    = \"SQL Connection String\"\n}",
  "fix_summary": "Added 'expiration_date' and 'content_type' to the 'database_connection_string' secret to improve its management and clarity."
}
